const item = $input.first().json;
const steps = Array.isArray(item.intermediateSteps) ? item.intermediateSteps : [];
const tools = [];
for (const s of steps) {
  const t = s && s.action && s.action.tool;
  if (t && !tools.includes(t)) tools.push(t);
}
return [{ json: { output: item.output || '', tools_used: tools } }];
